AND EXISTS ( SELECT 1 FROM media_asset asset WHERE asset.id = media_asset_return.asset_id AND asset.deleted_at = 0 AND COALESCE( CASE WHEN JSON_VALID(asset.secret_data) THEN JSON_UNQUOTE(JSON_EXTRACT(asset.secret_data, '$.inventorySubtype')) ELSE NULL END, CASE WHEN media_asset_return.asset_type = 'PERSONAL' THEN 'personal' END ) = #{assetSubtype} )
